using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "HourglassModuleOmenData", menuName = "Data/Battle/Omens System/Omen Data/Sothis/HourglassModuleOmenData")]
public class HourglassModuleOmenData : OnStartOfBattleOmenData
{
	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<SothisOmensHandler>.Instance.HourglassModuleOmenAction = delegate
		{
			omenInstance.EnqueueOmenFeedbackAndPlay();
		};
		base.Initialize(omenInstance);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<SothisOmensHandler>.Instance.HourglassModuleOmenAction = null;
		base.OmenRemoved();
	}

	public override string OmenConvertedDescription()
	{
		return GetOmenRawLocalizedDescription() + "\n" + GetStartOfBattleFormatedDescription();
	}
}
